// frontend/src/App.js
import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import "./App.css";

function App() {
  const [message, setMessage] = useState("");
  const [chat, setChat] = useState([]);
  const [loading, setLoading] = useState(false);
  const chatRef = useRef();

  useEffect(() => {
    if (chatRef.current) {
      chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [chat, loading]);

  async function sendMessage(e) {
    e.preventDefault();
    if (!message.trim()) return;

    const userMsg = { sender: "You", text: message };
    setChat((c) => [...c, userMsg]);
    setMessage("");
    setLoading(true);

    try {
      const res = await axios.post("http://localhost:5000/api/chat", {
        message,
        history: chat,
      });

      setChat((c) => [...c, { sender: "Sallu", text: res.data.reply }]);
    } catch (err) {
      setChat((c) => [
        ...c,
        { sender: "Sallu", text: "Error: could not reach backend" },
      ]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="page">
      <header className="header">
        <img src="https://cdn-icons-png.flaticon.com/512/4712/4712100.png" className="logo" />
        <span>Sallu AI Chatbot</span>
      </header>

      <div className="chat-box" ref={chatRef}>
        {chat.map((m, i) => (
          <div key={i} className={m.sender === "You" ? "msg user" : "msg bot"}>
            <div className="sender">{m.sender}</div>
            <div className="bubble">{m.text}</div>
          </div>
        ))}

        {loading && (
          <div className="msg bot">
            <div className="sender">Sallu</div>
            <div className="bubble typing">•••</div>
          </div>
        )}
      </div>

      <form className="input-bar" onSubmit={sendMessage}>
        <input
          type="text"
          placeholder="Send a message..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
        />
        <button type="submit">➤</button>
      </form>
    </div>
  );
}

export default App;
